class Solution {
public:
    bool validateBinaryTreeNodes(int n, vector<int>& leftChild, vector<int>& rightChild) {
        vector<int> parentCount(n, 0);
        for (int i = 0; i < n; i++) {
            if (leftChild[i] != -1) parentCount[leftChild[i]]++;
            if (rightChild[i] != -1) parentCount[rightChild[i]]++;
        }

        int root = -1;
        for (int i = 0; i < n; i++) {
            if (parentCount[i] > 1) return false;
            if (parentCount[i] == 0) {
                if (root != -1) return false;
                root = i;
            }
        }
        if (root == -1) return false;

        vector<bool> visited(n, false);
        queue<int> q;
        q.push(root);
        int count = 0;
        while (!q.empty()) {
            int node = q.front();
            q.pop();
            if (visited[node]) continue;
            visited[node] = true;
            count++;
            if (leftChild[node] != -1) q.push(leftChild[node]);
            if (rightChild[node] != -1) q.push(rightChild[node]);
        }

        return count == n;
    }
};
